// ─────────────────────────────────────────────────────────────────
//  App.jsx  —  Plaid Integration Frontend
// ─────────────────────────────────────────────────────────────────

import React, { useState, useCallback, useEffect } from "react";
import { usePlaidLink } from "react-plaid-link";

const API = "http://localhost:3001";
const USER_ID = "demo-user";

// ── Styles ────────────────────────────────────────────────────────
const styles = {
  root: {
    minHeight: "100vh",
    background: "#0a0a0a",
    color: "#f0ede8",
    fontFamily: "'Syne', sans-serif",
    padding: "0",
    margin: "0",
  },
  header: {
    borderBottom: "1px solid #222",
    padding: "24px 40px",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    background: "#0d0d0d",
  },
  logo: {
    fontSize: "20px",
    fontWeight: 800,
    letterSpacing: "-0.5px",
    color: "#f0ede8",
  },
  logoAccent: { color: "#00e5a0" },
  envBadge: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "11px",
    background: "#1a2e20",
    color: "#00e5a0",
    padding: "4px 10px",
    borderRadius: "4px",
    border: "1px solid #00e5a020",
  },
  main: { maxWidth: "900px", margin: "0 auto", padding: "60px 40px" },
  hero: { marginBottom: "60px" },
  heroTitle: {
    fontSize: "52px",
    fontWeight: 800,
    lineHeight: 1.05,
    letterSpacing: "-2px",
    marginBottom: "16px",
    color: "#f0ede8",
  },
  heroSub: {
    fontSize: "16px",
    color: "#888",
    fontFamily: "'IBM Plex Mono', monospace",
    lineHeight: 1.6,
  },
  stepList: {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: "12px",
    margin: "32px 0 48px",
  },
  step: (done) => ({
    padding: "14px 18px",
    border: `1px solid ${done ? "#00e5a030" : "#222"}`,
    borderRadius: "8px",
    background: done ? "#0d1f15" : "#111",
    display: "flex",
    alignItems: "center",
    gap: "12px",
    transition: "all 0.3s",
  }),
  stepDot: (done) => ({
    width: "8px",
    height: "8px",
    borderRadius: "50%",
    background: done ? "#00e5a0" : "#333",
    flexShrink: 0,
    transition: "all 0.3s",
    boxShadow: done ? "0 0 8px #00e5a080" : "none",
  }),
  stepLabel: (done) => ({
    fontSize: "13px",
    fontFamily: "'IBM Plex Mono', monospace",
    color: done ? "#00e5a0" : "#555",
    transition: "color 0.3s",
  }),
  connectBtn: {
    background: "#00e5a0",
    color: "#000",
    border: "none",
    padding: "16px 36px",
    fontSize: "16px",
    fontWeight: 700,
    fontFamily: "'Syne', sans-serif",
    borderRadius: "8px",
    cursor: "pointer",
    letterSpacing: "-0.3px",
    transition: "all 0.2s",
  },
  loadingBtn: {
    background: "#1a2e20",
    color: "#00e5a080",
    border: "1px solid #00e5a020",
    padding: "16px 36px",
    fontSize: "16px",
    fontWeight: 700,
    fontFamily: "'Syne', sans-serif",
    borderRadius: "8px",
    cursor: "not-allowed",
    letterSpacing: "-0.3px",
  },
  hint: {
    marginTop: "12px",
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "12px",
    color: "#555",
  },
  hintAccent: { color: "#00e5a080" },
  section: { marginTop: "60px" },
  sectionHeader: {
    display: "flex",
    alignItems: "baseline",
    gap: "12px",
    marginBottom: "24px",
    borderBottom: "1px solid #1a1a1a",
    paddingBottom: "16px",
  },
  sectionTitle: {
    fontSize: "22px",
    fontWeight: 700,
    letterSpacing: "-0.5px",
  },
  sectionCount: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "12px",
    color: "#555",
  },
  accountGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))",
    gap: "16px",
  },
  accountCard: {
    background: "#111",
    border: "1px solid #1e1e1e",
    borderRadius: "12px",
    padding: "24px",
    position: "relative",
    overflow: "hidden",
  },
  accountType: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "10px",
    color: "#555",
    textTransform: "uppercase",
    letterSpacing: "1px",
    marginBottom: "8px",
  },
  accountName: {
    fontSize: "17px",
    fontWeight: 700,
    marginBottom: "4px",
    letterSpacing: "-0.3px",
  },
  accountMask: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "12px",
    color: "#555",
    marginBottom: "20px",
  },
  balanceRow: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "baseline",
    marginBottom: "6px",
  },
  balanceLabel: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "11px",
    color: "#555",
  },
  balanceValue: (available) => ({
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "18px",
    fontWeight: 500,
    color: available ? "#00e5a0" : "#f0ede8",
  }),
  txTable: { width: "100%", borderCollapse: "collapse" },
  txHead: {
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "10px",
    color: "#555",
    textTransform: "uppercase",
    letterSpacing: "1px",
    textAlign: "left",
    padding: "8px 12px",
    borderBottom: "1px solid #1a1a1a",
  },
  txRow: (i) => ({
    borderBottom: "1px solid #111",
    background: i % 2 === 0 ? "transparent" : "#0d0d0d",
  }),
  txCell: {
    padding: "10px 12px",
    fontSize: "13px",
    fontFamily: "'IBM Plex Mono', monospace",
    color: "#888",
  },
  txName: {
    padding: "10px 12px",
    fontSize: "14px",
    fontWeight: 600,
    color: "#d0cdc8",
  },
  txAmount: (amount) => ({
    padding: "10px 12px",
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "14px",
    fontWeight: 500,
    color: amount > 0 ? "#ff6b6b" : "#00e5a0",
    textAlign: "right",
  }),
  error: {
    background: "#1a0d0d",
    border: "1px solid #ff6b6b30",
    borderRadius: "8px",
    padding: "16px 20px",
    color: "#ff6b6b",
    fontFamily: "'IBM Plex Mono', monospace",
    fontSize: "13px",
    marginTop: "20px",
  },
  pending: {
    display: "inline-block",
    background: "#1a1500",
    color: "#ffb347",
    fontSize: "10px",
    fontFamily: "'IBM Plex Mono', monospace",
    padding: "2px 6px",
    borderRadius: "3px",
    marginLeft: "6px",
  },
  tag: {
    display: "inline-block",
    background: "#1a1a2e",
    color: "#7b9fff",
    fontSize: "10px",
    fontFamily: "'IBM Plex Mono', monospace",
    padding: "2px 7px",
    borderRadius: "3px",
  },
};

// ── Format currency ───────────────────────────────────────────────
const fmt = (n, code = "USD") =>
  n == null
    ? "—"
    : new Intl.NumberFormat("en-US", { style: "currency", currency: code }).format(n);

// ── Account Card ─────────────────────────────────────────────────
function AccountCard({ account }) {
  const { name, official_name, type, subtype, mask, balances } = account;
  return (
    <div style={styles.accountCard}>
      <div style={styles.accountType}>{type} · {subtype}</div>
      <div style={styles.accountName}>{name}</div>
      <div style={styles.accountMask}>
        {official_name || name} ···· {mask}
      </div>
      <div style={styles.balanceRow}>
        <span style={styles.balanceLabel}>Available</span>
        <span style={styles.balanceValue(true)}>
          {fmt(balances.available, balances.iso_currency_code)}
        </span>
      </div>
      <div style={styles.balanceRow}>
        <span style={styles.balanceLabel}>Current</span>
        <span style={styles.balanceValue(false)}>
          {fmt(balances.current, balances.iso_currency_code)}
        </span>
      </div>
      {balances.limit && (
        <div style={styles.balanceRow}>
          <span style={styles.balanceLabel}>Credit Limit</span>
          <span style={styles.balanceValue(false)}>
            {fmt(balances.limit, balances.iso_currency_code)}
          </span>
        </div>
      )}
    </div>
  );
}

// ── Transaction Row ───────────────────────────────────────────────
function TxRow({ tx, index }) {
  return (
    <tr style={styles.txRow(index)}>
      <td style={styles.txCell}>{tx.date}</td>
      <td style={styles.txName}>
        {tx.merchant_name || tx.name}
        {tx.pending && <span style={styles.pending}>pending</span>}
      </td>
      <td style={styles.txCell}>
        {tx.category && <span style={styles.tag}>{tx.category}</span>}
      </td>
      <td style={styles.txAmount(tx.amount)}>
        {tx.amount > 0 ? "-" : "+"}
        {fmt(Math.abs(tx.amount), tx.currency)}
      </td>
    </tr>
  );
}

// ── Main App ──────────────────────────────────────────────────────
export default function App() {
  const [linkToken, setLinkToken] = useState(null);
  const [connected, setConnected] = useState(false);
  const [accounts, setAccounts] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [txMeta, setTxMeta] = useState(null);
  const [loading, setLoading] = useState({ link: true, accounts: false, tx: false });
  const [error, setError] = useState(null);

  // ── STEP 2A: Fetch link_token on mount ─────────────────────────
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch(`${API}/create_link_token`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userId: USER_ID }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error);
        setLinkToken(data.link_token);
      } catch (e) {
        setError(`Failed to get link token: ${e.message}`);
      } finally {
        setLoading((l) => ({ ...l, link: false }));
      }
    })();
  }, []);

  // ── STEP 5: Fetch accounts + transactions after connection ──────
  const fetchData = useCallback(async () => {
    setLoading((l) => ({ ...l, accounts: true, tx: true }));

    // Accounts (balances)
    try {
      const res = await fetch(`${API}/accounts?userId=${USER_ID}`);
      const data = await res.json();
      if (data.error) throw new Error(data.error);
      setAccounts(data.accounts);
    } catch (e) {
      setError(`Accounts fetch failed: ${e.message}`);
    } finally {
      setLoading((l) => ({ ...l, accounts: false }));
    }

    // Transactions (30 days)
    try {
      const res = await fetch(`${API}/transactions?userId=${USER_ID}`);
      const data = await res.json();
      if (data.error) throw new Error(data.error);
      setTransactions(data.transactions);
      setTxMeta({ total: data.total, ...data.date_range });
    } catch (e) {
      setError(`Transactions fetch failed: ${e.message}`);
    } finally {
      setLoading((l) => ({ ...l, tx: false }));
    }
  }, []);

  // ── STEP 2B: Exchange public_token after Plaid Link success ────
  const onSuccess = useCallback(
    async (public_token, metadata) => {
      // Step 4: metadata.institution gives you the connected institution
      console.log("✅ Plaid Link success!", metadata.institution);

      try {
        const res = await fetch(`${API}/exchange_public_token`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ public_token, userId: USER_ID }),
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error);

        setConnected(true);
        fetchData(); // Step 5: auto-fetch data
      } catch (e) {
        setError(`Token exchange failed: ${e.message}`);
      }
    },
    [fetchData]
  );

  // ── STEP 3: Plaid Link hook ─────────────────────────────────────
  const { open, ready } = usePlaidLink({
    token: linkToken,
    onSuccess,
    onExit: (err) => {
      if (err) setError(`Plaid Link exited with error: ${err.message}`);
    },
  });

  const steps = [
    { label: "backend scaffolded", done: true },
    { label: "link_token endpoint", done: !!linkToken },
    { label: "exchange_public_token", done: connected },
    { label: "plaid link UI mounted", done: !!linkToken },
    { label: "wells fargo connected", done: connected },
    { label: "balances fetched", done: accounts.length > 0 },
    { label: "transactions fetched", done: transactions.length > 0 },
  ];

  return (
    <div style={styles.root}>
      {/* Header */}
      <header style={styles.header}>
        <div style={styles.logo}>
          plaid<span style={styles.logoAccent}>.</span>app
        </div>
        <div style={styles.envBadge}>ENV: SANDBOX</div>
      </header>

      <main style={styles.main}>
        {/* Hero */}
        <div style={styles.hero}>
          <h1 style={styles.heroTitle}>
            Connect your<br />
            bank account.
          </h1>
          <p style={styles.heroSub}>
            Node.js + React + Plaid Link integration.<br />
            Sandbox mode — use Wells Fargo test credentials.
          </p>

          {/* Step status grid */}
          <div style={styles.stepList}>
            {steps.map((s, i) => (
              <div key={i} style={styles.step(s.done)}>
                <div style={styles.stepDot(s.done)} />
                <span style={styles.stepLabel(s.done)}>{s.label}</span>
              </div>
            ))}
          </div>

          {/* Connect button — STEP 3 & 4 */}
          {!connected ? (
            <>
              <button
                style={loading.link || !ready ? styles.loadingBtn : styles.connectBtn}
                onClick={() => open()}
                disabled={loading.link || !ready}
                onMouseOver={(e) => {
                  if (ready) e.target.style.background = "#00c98d";
                }}
                onMouseOut={(e) => {
                  if (ready) e.target.style.background = "#00e5a0";
                }}
              >
                {loading.link ? "Loading Plaid…" : "Connect Bank Account →"}
              </button>
              <p style={styles.hint}>
                In the Plaid Link dialog, select{" "}
                <span style={styles.hintAccent}>Wells Fargo</span> and use
                sandbox credentials:
                {" "}<span style={styles.hintAccent}>user_good</span> /{" "}
                <span style={styles.hintAccent}>pass_good</span>
              </p>
            </>
          ) : (
            <button
              style={{ ...styles.connectBtn, background: "#1a2e20", color: "#00e5a0" }}
              onClick={fetchData}
            >
              ↻ Refresh Data
            </button>
          )}

          {error && <div style={styles.error}>⚠ {error}</div>}
        </div>

        {/* STEP 5A — Account Balances */}
        {accounts.length > 0 && (
          <div style={styles.section}>
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>Account Balances</h2>
              <span style={styles.sectionCount}>{accounts.length} accounts</span>
            </div>
            <div style={styles.accountGrid}>
              {accounts.map((a) => (
                <AccountCard key={a.account_id} account={a} />
              ))}
            </div>
          </div>
        )}

        {/* STEP 5B — Transactions */}
        {transactions.length > 0 && (
          <div style={styles.section}>
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>Transactions</h2>
              <span style={styles.sectionCount}>
                {txMeta?.total} total · {txMeta?.start} → {txMeta?.end}
              </span>
            </div>
            <table style={styles.txTable}>
              <thead>
                <tr>
                  <th style={styles.txHead}>Date</th>
                  <th style={styles.txHead}>Name</th>
                  <th style={styles.txHead}>Category</th>
                  <th style={{ ...styles.txHead, textAlign: "right" }}>Amount</th>
                </tr>
              </thead>
              <tbody>
                {transactions.map((tx, i) => (
                  <TxRow key={tx.transaction_id} tx={tx} index={i} />
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}
